INSERT INTO recipe (id, title, ingredients_raw, instructions_raw, source_type, review_count, wish_count, avg_score, source_ref, version) VALUES
(1, '김치찌개', '고추 2개, 연근 200g, 설탕 1큰술, 된장 2큰술, 고춧가루 1큰술, 파프리카 1개, 떡 300g', '1. 고기를 먹기 좋은 크기로 썬다\n2. 밥과 함께 담아낸다\n3. 대파를 넣고 한소끔 끓인다\n4. 참기름을 두르고 불을 끈다', 'EXTERNAL_API', 21, 28, 3.1, 'RCP_001', 0),
(2, '된장찌개', '밀가루 1컵, 대파 1대, 된장 2큰술, 가지 2개, 버섯 100g, 표고버섯 4개', '1. 양념장을 넣고 골고루 섞는다\n2. 뚜껑을 덮고 15분간 끓인다\n3. 양념을 만들어 재료에 버무린다\n4. 고기를 먼저 넣고 겉면이 익을 때까지 볶는다', 'EXTERNAL_API', 25, 18, 4.5, 'RCP_002', 0),
(3, '순두부찌개', '표고버섯 4개, 식용유 2큰술, 배즙 3큰술, 연근 200g', '1. 팬에 기름을 두르고 센 불에 달군다\n2. 대파를 넣고 한소끔 끓인다\n3. 냄비에 육수를 넣고 끓인다\n4. 접시에 보기 좋게 담아낸다\n5. 재료를 깨끗이 씻어 준비한다', 'EXTERNAL_API', 48, 23, 4.3, 'RCP_003', 0),
(4, '부대찌개', '양파 1개, 물 500ml, 굴소스 1큰술, 미역 20g, 고추 2개', '1. 재료를 깨끗이 씻어 준비한다\n2. 고기를 먹기 좋은 크기로 썬다\n3. 소금으로 간을 맞춘다', 'EXTERNAL_API', 6, 27, 2.2, 'RCP_004', 0),
(5, '청국장찌개', '밀가루 1컵, 물 500ml, 연근 200g, 대파 1대, 소고기 300g', '1. 밥과 함께 담아낸다\n2. 고기를 먹기 좋은 크기로 썬다\n3. 양념을 만들어 재료에 버무린다\n4. 양념장을 넣고 골고루 섞는다\n5. 두부를 넣고 5분 더 끓인다', 'EXTERNAL_API', 35, 2, 3.6, 'RCP_005', 0),
(6, '동태찌개', '대파 1대, 시금치 100g, 감자 2개, 식용유 2큰술, 굴소스 1큰술, 오징어 1마리, 떡 300g, 표고버섯 4개', '1. 팬에 기름을 두르고 센 불에 달군다\n2. 참기름을 두르고 불을 끈다\n3. 고기를 먼저 넣고 겉면이 익을 때까지 볶는다\n4. 두부를 넣고 5분 더 끓인다\n5. 양념장을 넣고 골고루 섞는다', 'EXTERNAL_API', 43, 14, 1.5, 'RCP_006', 0),
(7, '참치김치찌개', '파프리카 1개, 소금 약간, 소고기 300g, 버섯 100g, 감자 2개, 쌈장 2큰술, 멸치 육수 500ml', '1. 양념장을 넣고 골고루 섞는다\n2. 재료를 깨끗이 씻어 준비한다\n3. 야채를 데쳐서 찬물에 헹군다\n4. 소금으로 간을 맞춘다\n5. 두부를 넣고 5분 더 끓인다', 'EXTERNAL_API', 48, 29, 1.4, 'RCP_007', 0),
(8, '꽁치김치찌개', '대파 1대, 김치 300g, 돼지고기 200g, 배즙 3큰술, 쌈장 2큰술, 새송이버섯 2개, 양배추 200g', '1. 물을 붓고 끓기 시작하면 중불로 줄인다\n2. 대파를 넣고 한소끔 끓인다\n3. 양념을 만들어 재료에 버무린다\n4. 접시에 보기 좋게 담아낸다\n5. 밥과 함께 담아낸다', 'EXTERNAL_API', 13, 28, 4.9, 'RCP_008', 0),
(9, '햄김치찌개', '쌈장 2큰술, 생강 1쪽, 어묵 200g, 다진마늘 1큰술, 새송이버섯 2개, 두부 1모', '1. 야채를 적당한 크기로 썰어 준비한다\n2. 야채를 데쳐서 찬물에 헹군다\n3. 접시에 보기 좋게 담아낸다\n4. 소금으로 간을 맞춘다', 'EXTERNAL_API', 28, 11, 2.5, 'RCP_009', 0),
(10, '소고기된장찌개', '소고기 300g, 고구마 2개, 새우 200g, 굴소스 1큰술, 생강 1쪽', '1. 물을 붓고 끓기 시작하면 중불로 줄인다\n2. 재료를 깨끗이 씻어 준비한다\n3. 그릇에 담아 깨소금을 뿌린다\n4. 야채를 데쳐서 찬물에 헹군다', 'EXTERNAL_API', 27, 3, 2.6, 'RCP_010', 0),
(11, '버섯된장찌개', '양파 1개, 고춧가루 1큰술, 고추장 2큰술, 버섯 100g, 당근 1/2개, 배즙 3큰술, 가지 2개, 맛술 1큰술', '1. 그릇에 담아 깨소금을 뿌린다\n2. 재료를 깨끗이 씻어 준비한다\n3. 물을 붓고 끓기 시작하면 중불로 줄인다\n4. 냄비에 육수를 넣고 끓인다\n5. 고기를 먹기 좋은 크기로 썬다', 'EXTERNAL_API', 48, 9, 3.4, 'RCP_011', 0),
(12, '조개된장찌개', '깨소금 1작은술, 배추 300g, 고추 2개, 무 200g, 대파 1대, 참기름 1큰술', '1. 냄비에 육수를 넣고 끓인다\n2. 고기를 먼저 넣고 겉면이 익을 때까지 볶는다\n3. 대파를 넣고 한소끔 끓인다\n4. 양념을 만들어 재료에 버무린다', 'EXTERNAL_API', 1, 3, 3.3, 'RCP_012', 0),
(13, '낙지찌개', '쌈장 2큰술, 돼지고기 200g, 떡 300g, 맛술 1큰술, 간장 3큰술, 설탕 1큰술, 양파 1개, 표고버섯 4개', '1. 뚜껑을 덮고 15분간 끓인다\n2. 고기를 먹기 좋은 크기로 썬다\n3. 두부를 넣고 5분 더 끓인다', 'EXTERNAL_API', 36, 15, 1.2, 'RCP_013', 0),
(14, '감자찌개', '소고기 300g, 대파 1대, 마늘 5쪽, 브로콜리 1개, 새우 200g', '1. 참기름을 두르고 불을 끈다\n2. 야채를 적당한 크기로 썰어 준비한다\n3. 고기를 먼저 넣고 겉면이 익을 때까지 볶는다\n4. 뚜껑을 덮고 15분간 끓인다', 'EXTERNAL_API', 49, 21, 1.3, 'RCP_014', 0),
(15, '두부찌개', '두부 1모, 느타리버섯 100g, 부추 100g, 설탕 1큰술, 버섯 100g', '1. 밥과 함께 담아낸다\n2. 그릇에 담아 깨소금을 뿌린다\n3. 약불에서 30분간 푹 끓인다', 'EXTERNAL_API', 20, 1, 3.3, 'RCP_015', 0),
(16, '열무된장찌개', '브로콜리 1개, 배추 300g, 당근 1/2개, 굴소스 1큰술', '1. 약불에서 30분간 푹 끓인다\n2. 두부를 넣고 5분 더 끓인다\n3. 팬에 기름을 두르고 센 불에 달군다', 'EXTERNAL_API', 31, 14, 3.2, 'RCP_016', 0),
(17, '고추장찌개', '설탕 1큰술, 생강 1쪽, 시금치 100g, 소금 약간, 닭고기 400g, 깨소금 1작은술', '1. 소금으로 간을 맞춘다\n2. 야채를 데쳐서 찬물에 헹군다\n3. 접시에 보기 좋게 담아낸다\n4. 양념장을 넣고 골고루 섞는다\n5. 밥과 함께 담아낸다', 'EXTERNAL_API', 44, 15, 4.8, 'RCP_017', 0),
(18, '굴된장찌개', '양배추 200g, 가지 2개, 생강 1쪽, 표고버섯 4개', '1. 고기를 먼저 넣고 겉면이 익을 때까지 볶는다\n2. 물을 붓고 끓기 시작하면 중불로 줄인다\n3. 고기를 먹기 좋은 크기로 썬다\n4. 뚜껑을 덮고 15분간 끓인다\n5. 접시에 보기 좋게 담아낸다', 'EXTERNAL_API', 20, 2, 3.1, 'RCP_018', 0),
(19, '차돌된장찌개', '감자 2개, 다진마늘 1큰술, 고춧가루 1큰술, 무 200g, 계란 2개', '1. 고기를 먹기 좋은 크기로 썬다\n2. 양파와 마늘을 넣고 향이 날 때까지 볶는다\n3. 접시에 보기 좋게 담아낸다', 'EXTERNAL_API', 50, 23, 3.4, 'RCP_019', 0),
(20, '콩비지찌개', '배즙 3큰술, 깻잎 10장, 대파 1대, 호박 1/2개, 부추 100g, 두부 1모', '1. 두부를 넣고 5분 더 끓인다\n2. 밥과 함께 담아낸다\n3. 참기름을 두르고 불을 끈다\n4. 냄비에 육수를 넣고 끓인다', 'EXTERNAL_API', 15, 16, 2.6, 'RCP_020', 0),
(21, '알탕찌개', '돼지고기 200g, 후추 약간, 무 200g, 생강 1쪽, 당면 200g', '1. 팬에 기름을 두르고 센 불에 달군다\n2. 양파와 마늘을 넣고 향이 날 때까지 볶는다\n3. 고기를 먼저 넣고 겉면이 익을 때까지 볶는다\n4. 접시에 보기 좋게 담아낸다', 'EXTERNAL_API', 34, 25, 3.5, 'RCP_021', 0),
(22, '어묵찌개', '두부 1모, 깨소금 1작은술, 피망 1개, 고구마 2개, 당근 1/2개, 양파 1개', '1. 대파를 넣고 한소끔 끓인다\n2. 팬에 기름을 두르고 센 불에 달군다\n3. 고기를 먼저 넣고 겉면이 익을 때까지 볶는다\n4. 냄비에 육수를 넣고 끓인다', 'EXTERNAL_API', 32, 18, 2.8, 'RCP_022', 0),
(23, '새우두부찌개', '깻잎 10장, 계란 2개, 새우 200g, 생강 1쪽, 떡 300g, 돼지고기 200g', '1. 냄비에 육수를 넣고 끓인다\n2. 접시에 보기 좋게 담아낸다\n3. 소금으로 간을 맞춘다', 'EXTERNAL_API', 34, 15, 3.5, 'RCP_023', 0),
(24, '버섯순두부찌개', '피망 1개, 두부 1모, 맛술 1큰술, 당면 200g, 계란 2개', '1. 그릇에 담아 깨소금을 뿌린다\n2. 재료를 깨끗이 씻어 준비한다\n3. 냄비에 육수를 넣고 끓인다', 'EXTERNAL_API', 26, 19, 4.6, 'RCP_024', 0),
(25, '해물순두부찌개', '미역 20g, 대파 1대, 표고버섯 4개, 된장 2큰술, 김치 300g', '1. 고기를 먹기 좋은 크기로 썬다\n2. 재료를 깨끗이 씻어 준비한다\n3. 양념을 만들어 재료에 버무린다\n4. 두부를 넣고 5분 더 끓인다', 'EXTERNAL_API', 46, 2, 3.6, 'RCP_025', 0),
(26, '고등어김치찌개', '멸치 육수 500ml, 배추 300g, 김치 300g, 참기름 1큰술', '1. 대파를 넣고 한소끔 끓인다\n2. 뚜껑을 덮고 15분간 끓인다\n3. 야채를 데쳐서 찬물에 헹군다\n4. 약불에서 30분간 푹 끓인다\n5. 그릇에 담아 깨소금을 뿌린다', 'EXTERNAL_API', 40, 8, 4.9, 'RCP_026', 0),
(27, '돼지고기김치찌개', '쌀 2컵, 양파 1개, 닭고기 400g, 부추 100g, 브로콜리 1개, 다진마늘 1큰술, 피망 1개, 어묵 200g', '1. 야채를 적당한 크기로 썰어 준비한다\n2. 양념을 만들어 재료에 버무린다\n3. 대파를 넣고 한소끔 끓인다', 'EXTERNAL_API', 30, 24, 4.3, 'RCP_027', 0),
(28, '소시지찌개', '맛술 1큰술, 호박 1/2개, 고추 2개, 미역 20g, 느타리버섯 100g, 새우 200g, 김치 300g', '1. 재료를 깨끗이 씻어 준비한다\n2. 소금으로 간을 맞춘다\n3. 약불에서 30분간 푹 끓인다', 'EXTERNAL_API', 50, 1, 4.5, 'RCP_028', 0),
(29, '묵은지찌개', '떡 300g, 소고기 300g, 부추 100g, 후추 약간, 멸치 육수 500ml, 두부 1모', '1. 야채를 데쳐서 찬물에 헹군다\n2. 양파와 마늘을 넣고 향이 날 때까지 볶는다\n3. 재료를 깨끗이 씻어 준비한다\n4. 고기를 먹기 좋은 크기로 썬다\n5. 냄비에 육수를 넣고 끓인다', 'EXTERNAL_API', 10, 23, 5.0, 'RCP_029', 0),
(30, '두부김치찌개', '닭고기 400g, 다진마늘 1큰술, 식용유 2큰술, 계란 2개', '1. 물을 붓고 끓기 시작하면 중불로 줄인다\n2. 그릇에 담아 깨소금을 뿌린다\n3. 양파와 마늘을 넣고 향이 날 때까지 볶는다', 'EXTERNAL_API', 17, 28, 2.4, 'RCP_030', 0),
(31, '만두찌개', '간장 3큰술, 떡 300g, 쌀 2컵, 김치 300g', '1. 재료를 깨끗이 씻어 준비한다\n2. 양념장을 넣고 골고루 섞는다\n3. 그릇에 담아 깨소금을 뿌린다\n4. 소금으로 간을 맞춘다', 'EXTERNAL_API', 11, 23, 4.1, 'RCP_031', 0),
(32, '떡만두찌개', '참기름 1큰술, 다진마늘 1큰술, 식용유 2큰술, 연근 200g', '1. 팬에 기름을 두르고 센 불에 달군다\n2. 재료를 깨끗이 씻어 준비한다\n3. 야채를 데쳐서 찬물에 헹군다\n4. 약불에서 30분간 푹 끓인다\n5. 양념을 만들어 재료에 버무린다', 'EXTERNAL_API', 8, 12, 4.7, 'RCP_032', 0),
(33, '오징어찌개', '깻잎 10장, 피망 1개, 굴소스 1큰술, 시금치 100g', '1. 팬에 기름을 두르고 센 불에 달군다\n2. 냄비에 육수를 넣고 끓인다\n3. 고기를 먹기 좋은 크기로 썬다\n4. 뚜껑을 덮고 15분간 끓인다\n5. 재료를 깨끗이 씻어 준비한다', 'EXTERNAL_API', 47, 0, 2.7, 'RCP_033', 0),
(34, '우거지된장찌개', '당면 200g, 양파 1개, 표고버섯 4개, 브로콜리 1개', '1. 양념장을 넣고 골고루 섞는다\n2. 물을 붓고 끓기 시작하면 중불로 줄인다\n3. 냄비에 육수를 넣고 끓인다\n4. 대파를 넣고 한소끔 끓인다\n5. 재료를 깨끗이 씻어 준비한다', 'EXTERNAL_API', 8, 7, 3.7, 'RCP_034', 0),
(35, '들깨찌개', '양파 1개, 생강 1쪽, 다진마늘 1큰술, 배추 300g, 호박 1/2개, 버섯 100g', '1. 뚜껑을 덮고 15분간 끓인다\n2. 재료를 깨끗이 씻어 준비한다\n3. 접시에 보기 좋게 담아낸다', 'EXTERNAL_API', 0, 7, 3.1, 'RCP_035', 0),
(36, '미역된장찌개', '식용유 2큰술, 당근 1/2개, 브로콜리 1개, 계란 2개', '1. 재료를 깨끗이 씻어 준비한다\n2. 밥과 함께 담아낸다\n3. 대파를 넣고 한소끔 끓인다', 'EXTERNAL_API', 4, 29, 2.6, 'RCP_036', 0),
(37, '호박된장찌개', '식용유 2큰술, 닭고기 400g, 배추 300g, 김치 300g', '1. 대파를 넣고 한소끔 끓인다\n2. 재료를 깨끗이 씻어 준비한다\n3. 양파와 마늘을 넣고 향이 날 때까지 볶는다', 'EXTERNAL_API', 32, 18, 2.3, 'RCP_037', 0),
(38, '가지된장찌개', '삼겹살 300g, 팽이버섯 100g, 호박 1/2개, 양파 1개', '1. 밥과 함께 담아낸다\n2. 냄비에 육수를 넣고 끓인다\n3. 재료를 깨끗이 씻어 준비한다', 'EXTERNAL_API', 43, 10, 3.5, 'RCP_038', 0),
(39, '배추된장찌개', '고춧가루 1큰술, 쌀 2컵, 감자 2개, 파프리카 1개, 대파 1대, 호박 1/2개', '1. 소금으로 간을 맞춘다\n2. 양파와 마늘을 넣고 향이 날 때까지 볶는다\n3. 팬에 기름을 두르고 센 불에 달군다\n4. 약불에서 30분간 푹 끓인다', 'EXTERNAL_API', 0, 2, 3.5, 'RCP_039', 0),
(40, '무된장찌개', '삼겹살 300g, 간장 3큰술, 양배추 200g, 계란 2개', '1. 밥과 함께 담아낸다\n2. 양념을 만들어 재료에 버무린다\n3. 야채를 데쳐서 찬물에 헹군다\n4. 소금으로 간을 맞춘다', 'EXTERNAL_API', 1, 16, 1.1, 'RCP_040', 0),
(41, '팽이버섯찌개', '양파 1개, 김치 300g, 미역 20g, 당면 200g, 버섯 100g, 호박 1/2개, 소고기 300g', '1. 접시에 보기 좋게 담아낸다\n2. 냄비에 육수를 넣고 끓인다\n3. 소금으로 간을 맞춘다\n4. 고기를 먼저 넣고 겉면이 익을 때까지 볶는다', 'EXTERNAL_API', 16, 30, 4.8, 'RCP_041', 0),
(42, '느타리버섯찌개', '어묵 200g, 간장 3큰술, 브로콜리 1개, 쌈장 2큰술, 양배추 200g, 밀가루 1컵', '1. 재료를 깨끗이 씻어 준비한다\n2. 물을 붓고 끓기 시작하면 중불로 줄인다\n3. 두부를 넣고 5분 더 끓인다\n4. 야채를 데쳐서 찬물에 헹군다\n5. 밥과 함께 담아낸다', 'EXTERNAL_API', 22, 24, 3.4, 'RCP_042', 0),
(43, '양배추된장찌개', '대파 1대, 후추 약간, 두부 1모, 콩나물 200g, 버섯 100g', '1. 약불에서 30분간 푹 끓인다\n2. 고기를 먹기 좋은 크기로 썬다\n3. 야채를 데쳐서 찬물에 헹군다\n4. 팬에 기름을 두르고 센 불에 달군다\n5. 뚜껑을 덮고 15분간 끓인다', 'EXTERNAL_API', 35, 30, 1.0, 'RCP_043', 0),
(44, '고구마순된장찌개', '시금치 100g, 미역 20g, 가지 2개, 콩나물 200g, 참기름 1큰술, 굴소스 1큰술', '1. 밥과 함께 담아낸다\n2. 팬에 기름을 두르고 센 불에 달군다\n3. 그릇에 담아 깨소금을 뿌린다\n4. 참기름을 두르고 불을 끈다', 'EXTERNAL_API', 50, 6, 3.6, 'RCP_044', 0),
(45, '시래기된장찌개', '고춧가루 1큰술, 가지 2개, 고구마 2개, 피망 1개, 양파 1개', '1. 양파와 마늘을 넣고 향이 날 때까지 볶는다\n2. 고기를 먼저 넣고 겉면이 익을 때까지 볶는다\n3. 양념장을 넣고 골고루 섞는다', 'EXTERNAL_API', 23, 2, 3.6, 'RCP_045', 0),
(46, '달걀찌개', '호박 1/2개, 참기름 1큰술, 고구마 2개, 물 500ml, 김치 300g, 느타리버섯 100g', '1. 재료를 깨끗이 씻어 준비한다\n2. 물을 붓고 끓기 시작하면 중불로 줄인다\n3. 접시에 보기 좋게 담아낸다', 'EXTERNAL_API', 44, 16, 3.4, 'RCP_046', 0),
(47, '김치만두찌개', '소고기 300g, 표고버섯 4개, 피망 1개, 닭고기 400g, 후추 약간', '1. 물을 붓고 끓기 시작하면 중불로 줄인다\n2. 양념장을 넣고 골고루 섞는다\n3. 재료를 깨끗이 씻어 준비한다\n4. 양념을 만들어 재료에 버무린다', 'EXTERNAL_API', 18, 3, 3.4, 'RCP_047', 0),
(48, '해물김치찌개', '고추 2개, 쌈장 2큰술, 깻잎 10장, 표고버섯 4개, 새송이버섯 2개', '1. 물을 붓고 끓기 시작하면 중불로 줄인다\n2. 냄비에 육수를 넣고 끓인다\n3. 팬에 기름을 두르고 센 불에 달군다\n4. 뚜껑을 덮고 15분간 끓인다\n5. 고기를 먹기 좋은 크기로 썬다', 'EXTERNAL_API', 35, 0, 3.8, 'RCP_048', 0),
(49, '닭볶음탕찌개', '소고기 300g, 연근 200g, 김치 300g, 밀가루 1컵, 식용유 2큰술, 미역 20g', '1. 약불에서 30분간 푹 끓인다\n2. 재료를 깨끗이 씻어 준비한다\n3. 그릇에 담아 깨소금을 뿌린다\n4. 냄비에 육수를 넣고 끓인다', 'EXTERNAL_API', 48, 8, 4.6, 'RCP_049', 0),
(50, '돼지갈비찌개', '어묵 200g, 고추 2개, 참기름 1큰술, 표고버섯 4개', '1. 팬에 기름을 두르고 센 불에 달군다\n2. 양념을 만들어 재료에 버무린다\n3. 양파와 마늘을 넣고 향이 날 때까지 볶는다', 'EXTERNAL_API', 11, 0, 1.6, 'RCP_050', 0);
